    "summary": "六萬多字的小書，一個晚上就能看完，後勁卻很長。媽媽和女兒輪流講同一段日子，兩邊都有委屈，兩邊都說得通，看到後面很難只站在其中一邊。5 顆星我給得很乾脆。",
