            "id": "nov2627",
            "note": "約 380 萬字。警校畢業生穿成古代小捕快，靠刑偵思路破了稅銀案，前半本一案扣一案，京城那段停不下來。魏淵是全書最有重量的角色。後宮向，後半辦案變少、戰力膨脹。"
